var tmpFileInput = document.createElement('input');
tmpFileInput.type = 'file';
tmpFileInput.id = 'upload_file';
tmpFileInput.name = 'upload_file';

tmpFileInput.onchange = function(fe) {
    var files = fe.currentTarget.files;

    if (!sealImgExtCheck(fe.currentTarget.value)) {
        Alert(Sepoa.cache.text.get('SLM_133.MESSAGE012')); //이미지 파일만 등록할 수 있습니다. (jpg|jpeg|png)
        return;
    }

    //formObj.checkItem('SEAL_IMG_FLAG');
    $sealImgFile = files;
    doSetImgThumb(files);
}

tmpFileInput.click();


var reg = /(.*?)\.(jpg|jpeg|png)$/;
if (value.match(reg)) {
    return true;
} else {
    return false;
}


var container = formObj.getContainer('CHANGE_SEAL_IMG_BOX');
container.innerHTML = '';

for (var image of files) {
    var reader = new FileReader();

    reader.onload = function(event) {
        var img = document.createElement("img");
        img.setAttribute("src", event.target.result);
        img.style.width = '100%';

        container.appendChild(img);
        setImageCover('CHANGE_SEAL_IMG_BOX');
    }
    reader.readAsDataURL(image);
}


